-- communion.user.identity 批量更新：按厂商编号(OC)清单回填社会统一信用代码（待生产）
-- 需求：userId = 清单列1(OC-xxxxx)，identity 更新为列2(18位统一信用代码)。
-- 清单：3124 行，userId 无重复，信用代码全部 18 位（2026-10-05 解析校验）。
-- 数据现状(2026-10-05 生产)：user 表 OC-* 用户 4412 个（type=1 供应商），identity 空 3968 / 已填 444；
--   identity 为明文口径（varchar(128)，syncSupplier 同款直接落信用代码）。
-- 执行方式：三步临时表（同 USERINFO_EMAIL_UPDATE_DINGTALK 先例）。
-- 幂等：可重复执行（UPDATE 天然幂等；stage 表 DROP 重建）。

-- ========== 1. 建临时清单表并导入 ==========
DROP TABLE IF EXISTS communion.tmp_user_identity_oc;
CREATE TABLE communion.tmp_user_identity_oc (
    userId  varchar(20) NOT NULL,
    identity varchar(128) NOT NULL,
    PRIMARY KEY (userId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;








-- ========== 2. 执行前核验（人工过目） ==========
-- 2a. 清单内 userId 在 user 表的匹配情况（预期 matched + missing = 3124）
SELECT
    (SELECT COUNT(*) FROM communion.tmp_user_identity_oc t) AS list_total,
    (SELECT COUNT(*) FROM communion.tmp_user_identity_oc t JOIN communion.user u ON u.userId = t.userId) AS matched,
    (SELECT COUNT(*) FROM communion.tmp_user_identity_oc t
     LEFT JOIN communion.user u ON u.userId = t.userId WHERE u.userId IS NULL) AS missing_in_user;

-- 2b. 不匹配明细（如有, 人工确认编号是否录入错/未同步）
-- SELECT t.* FROM communion.tmp_user_identity_oc t
-- LEFT JOIN communion.user u ON u.userId = t.userId WHERE u.userId IS NULL;

-- 2c. 将被覆盖已有 identity 的行（syncSupplier 曾落部分信用代码, 确认覆盖无异议）
-- SELECT u.userId, u.identity AS old_identity, t.identity AS new_identity
-- FROM communion.tmp_user_identity_oc t
-- JOIN communion.user u ON u.userId = t.userId
-- WHERE u.identity <> '' AND u.identity <> t.identity;

-- ========== 3. 执行更新 ==========
UPDATE communion.user u
JOIN communion.tmp_user_identity_oc t ON t.userId = u.userId
SET u.identity = t.identity;

-- ========== 4. 执行后核验（预期 updated_rows = 实际匹配行数; remaining = 0） ==========
SELECT ROW_COUNT() AS updated_rows;

SELECT COUNT(*) AS remaining_mismatch
FROM communion.tmp_user_identity_oc t
JOIN communion.user u ON u.userId = t.userId
WHERE u.identity <> t.identity;

-- ========== 5. 清理 ==========
DROP TABLE IF EXISTS communion.tmp_user_identity_oc;
